    ps_box(ps_block_front,ps_block_back,ps_nose_y0,ps_seat_y1+travel,
        -ps_block_half_z,ps_block_half_z);
    ps_box(ps_lip_x0,ps_lip_x1,ps_lip_y0,ps_seat_y1+travel,
